# Raise a claim's proofs count by one. A SETTLED or VOID claim, or a claim dated inside a closed period, is refused
# (400) and writes nothing.
archived:
  class: net.officefloor.hq.app.sheet.CheckNotArchived
  next: viewer
viewer:
  class: net.officefloor.hq.app.setting.CheckNotViewer
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkPeriod
checkPeriod:
  class: net.officefloor.hq.app.claim.CheckClaimPeriodOpen
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.claim.CheckClaimProof
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.claim.AddClaimProof
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimProofAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Remind an OPEN or PENDING claim: records the sheet's today as the day it was last reminded and writes REMIND.
# A claim in any other status, or one already reminded on the sheet's today, is refused (400) and writes nothing.
archived:
  class: net.officefloor.hq.app.sheet.CheckNotArchived
  next: viewer
viewer:
  class: net.officefloor.hq.app.setting.CheckNotViewer
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.claim.CheckClaimRemind
  govern: [ transaction ]
  next: remind
remind:
  class: net.officefloor.hq.app.claim.RemindClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Raises the claim's proofs count by one. */
public class AddClaimProof {
    public void add(@Val Claim claim, ClaimRepository repository, Out<Claim> proved) {
        Claim next = claim.withProof();
        repository.saveProofs(next);
        proved.set(next);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Refuses (400) a proof for a SETTLED or VOID claim. */
public class CheckClaimProof {
    public void check(@Val Claim claim) throws InvalidClaimException {
        if (!claim.takesProof()) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be given a proof.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the proof just added to the claim, with its person's name, then the claim's proofs count. */
public class AuditClaimProofAdded {
    public void audit(@Val Claim claim, PersonRepository people, @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_PROOF_ADDED sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(claim.number()) + " proofs=" + claim.proofs());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Stores the sheet's today as the day the claim was last reminded. */
public class RemindClaim {
    public void remind(@Val Claim claim, ClaimRepository repository, SheetRepository sheets) {
        repository.remind(claim.sheetId(), claim.id(), sheets.today(claim.sheetId()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Refuses (400) a reminder unless the claim is OPEN or PENDING and was not already reminded on the sheet's today. */
public class CheckClaimRemind {
    public void check(@Val Claim claim, ClaimRepository repository, SheetRepository sheets)
            throws InvalidClaimException {
        if (!claim.status().open()) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be reminded.");
        }
        if (sheets.today(claim.sheetId()).equals(repository.reminded(claim.sheetId(), claim.id()))) {
            throw new InvalidClaimException("The claim was already reminded today.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim just reminded, with its person's name. */
public class AuditClaimReminded {
    public void audit(@Val Claim claim, PersonRepository people, @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("REMIND sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(claim.number()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

