package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaims {
    public void respond(@Val Sheet sheet, @Val List<Claim> claims, ClaimLogRepository logs, ClaimLockRepository locks,
            ClaimRepository repository, ObjectResponse<List<ClaimResponse>> response) {
        Map<Long, List<ClaimLogLine>> log = logs.findAll(sheet.id());
        Map<Long, String> locked = locks.findAll(sheet.id());
        Set<Long> late = repository.lateEntries(sheet.id());
        Map<Long, LocalDate> reminded = repository.remindedAll(sheet.id());
        Map<Long, String> refs = repository.refs(sheet.id());
        Map<Long, String> tags = repository.tagsAll(sheet.id());
        Map<Long, String> voidReasons = repository.voidReasons(sheet.id());
        response.send(claims.stream()
                .map((c) -> ClaimResponse.from(c, log.getOrDefault(c.id(), List.of()), locked.get(c.id()),
                        late.contains(c.id()), reminded.get(c.id()), refs.get(c.id()),
                        tags.get(c.id()), voidReasons.get(c.id()))).toList());
    }
}
-- A claim's status log: one line per status it has had, oldest first (id order) — the status, the user who
-- gave it, the sheet's today then, and the claim's due as computed at that moment ('n/a' when it had none).
CREATE TABLE claim_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    claim_id BIGINT NOT NULL REFERENCES claim (id),
    status VARCHAR(20) NOT NULL,
    by_user VARCHAR(200) NOT NULL,
    log_date DATE NOT NULL,
    due VARCHAR(30) NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
-- A claim's tags (null: none): lower-cased, sorted and comma separated. Every tag ever given to a claim on a sheet
-- stays on the sheet's tag list, even once no claim carries it.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
CREATE TABLE claim_tag (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    tag VARCHAR(1000) NOT NULL,
    PRIMARY KEY (sheet_id, tag)
);
-- The sheet's void reasons, in the order they were added: a reason is on a sheet's list at most once. While the list
-- is not empty, a claim is voided with a reason chosen from it, kept on the claim (null: voided with none).
CREATE TABLE void_reason (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason VARCHAR(200) NOT NULL,
    position INT NOT NULL,
    PRIMARY KEY (sheet_id, reason)
);
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
